SELECT *
FROM Students
WHERE date_first_registered = (
  SELECT MIN(date_first_registered) FROM Students
);

SELECT first_name
FROM Students
WHERE date_first_registered = (
  SELECT MIN(date_first_registered) FROM Students WHERE date_first_registered IS NOT NULL
);

SELECT first_name, middle_name
FROM Students
WHERE date_first_registered = (
  SELECT MIN(date_first_registered) FROM Students WHERE date_first_registered IS NOT NULL
);

SELECT first_name, middle_name, last_name
FROM Students
WHERE date_first_registered = (
  SELECT MIN(date_first_registered) FROM Students WHERE date_first_registered IS NOT NULL
);
